		NativeSlotLayout layout = new NativeSlotLayout(Map.of("s", 0, "p", 1, "o", 2, "x", 3, "y", 4), null);
		layout.freeze(List.of("s", "p", "o", "x", "y"));
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		ValuesRow[] input = {
				new ValuesRow(new int[] { 0 }, new long[] { 100L }),
				new ValuesRow(new int[] { 0 }, new long[] { 200L }),
				new ValuesRow(new int[] { 0 }, new long[] { 300L })
		};
		SlotPlan[] children = new SlotPlan[edgeCount + 1];
		children[0] = new ValuesPlan(input);
		int subjectSlot = 0;
		for (int edge = 0; edge < edgeCount; edge++) {
			int objectSlot = edge + 2;
			children[edge + 1] = new PatternPlan(Term.slot(subjectSlot), Term.slot(1), Term.slot(objectSlot),
					Term.unbound(), ContextConstraint.UNRESTRICTED, false, 96D);
			subjectSlot = objectSlot;
		}
		MultiJoinPlan join = new MultiJoinPlan(children, new MaskedFilter[0]);
		try (var proposal = LmdbWildcardPredicateBatch.propose(join, row, 32, false, new int[] { 0, 1, subjectSlot },
				new int[0])) {
			double firstStageWork = input.length * predicatePlanes;
			double secondStageWork = input.length * 4D;
			double thirdStageWork = edgeCount == 3 ? secondStageWork * 2D : 0D;
			assertThat(proposal).isNotNull();
			assertThat(proposal.costQuote().total().expected(Feature.HASH_PROBE))
					.isEqualTo(firstStageWork + secondStageWork + thirdStageWork);
		}
