	@Test
	void constantRootUsesTheCapturedEdgeCountForTheNextStage() {
		assertThat(constantRootQuote(32, 4D).total().expected(Feature.HASH_PROBE)).isEqualTo(32D + 120D);
	}

	@Test
	void limitedChainPricesTheFirstPrefixBatchSeparatelyFromItsFanOut() {
		LmdbNativeCostQuote quote = constantRootQuote(256, 100D);
		assertThat(quote.forSlice(1D).expected(Feature.HASH_PROBE)).isGreaterThanOrEqualTo(32D);
	}

	@Test
	void sampledFanOutDoesNotProveAnExactProbeCount() {
		LmdbNativeCostVector work = constantRootQuote(256, 100D).total();
		assertThat(work.low(Feature.HASH_PROBE)).isLessThan(work.expected(Feature.HASH_PROBE));
		assertThat(work.high(Feature.HASH_PROBE)).isGreaterThan(work.expected(Feature.HASH_PROBE));
	}

